const { ChatGPTProofOfWork } = require('./pow')
const { humanDelay } = require('../../utils/human-delay')
const { uuid } = require('../../utils/uuid')
const { BaseAPI } = require('../base/BaseAPI')
const { assertOk } = require('../../utils/http-error')

/**
 * ChatGPT API Client
 *
 * User pastes a full fetch() call from browser DevTools.
 * We extract headers + body, reuse all real values.
 *
 * CRITICAL: "Copy as fetch" omits User-Agent (browser adds it automatically).
 * We extract the real UA from the proof token config[4] and add it to every request.
 * Without User-Agent, Cloudflare returns 403.
 */
class ChatGPTAPI extends BaseAPI {
  static JSON_TIMEOUT = true

  constructor(options = {}) {
    super(options)
    this.BASE_URL = 'https://chatgpt.com'
    this._headers = null
    this._bodyTemplate = null
    this._config = null
    this._ready = false
    this._pageLoadedAt = Date.now()
  }

  async initializeFromJSON(data) {
    this._headers = data.headers
    this._bodyTemplate = data.body

    this._seedCookies()

    const existingProof = this._headers['openai-sentinel-proof-token']
    if (!existingProof) {
      throw new Error('openai-sentinel-proof-token not found in headers. Data is incomplete.')
    }
    this._config = ChatGPTProofOfWork.decodeProofToken(existingProof)

    const realUA = this._config[4]
    if (realUA && typeof realUA === 'string' && realUA.length > 20) {
      this._headers['user-agent'] = realUA
      // if (this._log) console.debug(`[ChatGPT] User-agent: ${realUA.slice(0, 60)}...`)
    }

    if (this._log) console.debug('[ChatGPT] Initialized from capture JSON')

    await this._refreshSentinel()
    this._ready = true
  }

  /**
   * Upload a file/image for a message attachment.
   * Mirrors ClaudeAPI.uploadFile — returns an attachment descriptor
   * to be pushed into the message's metadata.attachments[] array.
   *
   * @param {{ filename: string, data: Buffer, mimeType?: string }} file
   * @returns {Promise<{ id: string, size: number, name: string, mime_type: string, source: string }>}
   */
  async uploadFile(file) {
    const { filename, data, mimeType = 'application/octet-stream' } = file

    // Step 1: request an upload URL
    const prepRes = await this._fetch(
      `${this.BASE_URL}/backend-api/files`,
      {
        method: 'POST',
        headers: this._buildHeaders({ 'content-type': 'application/json' }, '/backend-api/files'),
        body: JSON.stringify({
          file_name: filename,
          file_size: data.length,
          mime_type: mimeType,
          use_case: 'ace_upload',
        }),
      },
      true,
    )

    const { upload_url: uploadUrl, file_id: fileId } = prepRes.data
    if (!uploadUrl || !fileId) {
      throw new Error(`ChatGPT file prepare failed: ${JSON.stringify(prepRes.data)}`)
    }

    // Step 2: PUT raw bytes to the Azure Blob SAS URL
    const putRes = await this._fetch(
      uploadUrl,
      {
        method: 'PUT',
        headers: { 'x-ms-blob-type': 'BlockBlob', 'content-type': mimeType },
        body: data,
      },
      false,
    )
    await assertOk(putRes, { prefix: 'ChatGPT blob upload failed: ' })

    // Step 3: trigger processing, wait for completion via SSE
    const processRes = await this._fetch(
      `${this.BASE_URL}/backend-api/files/process_upload_stream`,
      {
        method: 'POST',
        headers: this._buildHeaders(
          { accept: 'text/event-stream', 'content-type': 'application/json' },
          '/backend-api/files/process_upload_stream',
        ),
        body: JSON.stringify({
          file_id: fileId,
          file_name: filename,
          use_case: 'ace_upload',
          index_for_retrieval: false,
        }),
      },
      false,
    )

    await assertOk(processRes, { prefix: 'ChatGPT file processing failed: ' })

    const bodyText = await processRes.text()
    if (!bodyText.includes('file.processing.completed')) {
      throw new Error(`ChatGPT file processing did not complete: ${bodyText.slice(0, 300)}`)
    }

    if (this._log) {
      console.debug(`[ChatGPT] File uploaded: ${filename} (${data.length} bytes) → ${fileId}`)
    }

    return {
      id: fileId,
      size: data.length,
      name: filename,
      mime_type: mimeType,
      source: 'local',
    }
  }

  async chatCompletion(
    prompt,
    chatSessionId,
    parentMessageId = 'client-created-root',
    model = 'auto',
    attachments = [],
  ) {
    await humanDelay()
    if (!this._ready) throw new Error('Not initialized')

    const messageId = uuid()
    const partialQuery = {
      id: messageId,
      author: { role: 'user' },
      content: { content_type: 'text', parts: [prompt] },
    }

    await this._refreshSentinel()

    // Always prepare conversation before sending — matches browser HAR flow.
    // First turn: gets initial conduit_token. Follow-up turns: gets refreshed conduit_token.
    const mimeTypes = attachments.map((a) => a.mime_type).filter(Boolean)
    await this._prepareConversation(chatSessionId, parentMessageId, partialQuery, model, mimeTypes)

    const now = Date.now() / 1000

    const body = JSON.parse(JSON.stringify(this._bodyTemplate))
    body.action = 'next'
    body.messages = [
      {
        ...partialQuery,
        create_time: now,
        metadata: {
          ...(attachments.length > 0 && { attachments }),
          selected_github_repos: [],
          selected_all_github_repos: false,
          serialization_metadata: { custom_symbol_offsets: [] },
        },
      },
    ]
    body.conversation_id = chatSessionId
    body.parent_message_id = parentMessageId
    body.client_prepare_state = parentMessageId ? 'success' : 'sent'
    if (body.client_contextual_info) {
      // Real elapsed ms since this session's first request — mirrors browser's
      // performance.now()-based time_since_loaded, anchored to page-load time.
      body.client_contextual_info.time_since_loaded = Date.now() - this._pageLoadedAt
    }

    if (this._log)
      console.debug('[PROMPT] REQ', {
        chatSessionId,
        parentMessageId,
        prompt,
        promptLength: prompt.length,
      })

    const url = `${this.BASE_URL}/backend-api/f/conversation`

    const res = await this._fetch(url, {
      method: 'POST',
      headers: this._buildHeaders({ accept: 'text/event-stream' }, '/backend-api/f/conversation'),
      body: JSON.stringify(body),
    })

    if (this._log) console.debug(res.status, res.statusText)

    // Non-200 status is logged here; the error branch below throws for the caller to handle.
    // No automatic sentinel-refresh-and-retry is implemented.
    if (!res.ok) {
      const errText = await res.text()

      // 429 from ChatGPT means hourly limit hit — set provider cooldown
      if (res.status === 429) {
        const { setProviderCooldown } = require('../../utils/rate-limiter')
        // default: time left until the top of the next hour (ChatGPT's
        // limit is "N messages per hour", so it resets on the hour boundary,
        // not a flat 5min); override from body or retry-after header if present
        const now = new Date()
        let cooldownMs =
          ((60 - now.getUTCMinutes()) * 60 - now.getUTCSeconds()) * 1000 - now.getUTCMilliseconds()
        try {
          const body = JSON.parse(errText)
          if (body.cooldown_ms) cooldownMs = body.cooldown_ms
          else if (body.retry_after_ms) cooldownMs = body.retry_after_ms
        } catch (err) {
          console.error('JSON.parse() failed:', err)
          /* use default */
          console.error(err)
        }
        const retryAfter = res.headers.get('retry-after')
        if (retryAfter) {
          const sec = parseInt(retryAfter, 10)
          if (!isNaN(sec)) cooldownMs = sec * 1000
        }
        setProviderCooldown('ChatGPT', cooldownMs)
        const err = new Error(`ChatGPT error 429: ${errText.slice(0, 300)}`)
        err.status = 429
        err.statusCode = 429
        err.cooldownMs = cooldownMs
        throw err
      }

      // 403 "unusual activity" is Cloudflare's device/IP bot-behavior flag —
      // distinct from a stale-session 403. Retrying immediately just keeps
      // tripping the same detector, so cool down instead of hammering it.
      if (res.status === 403 && errText.toLowerCase().includes('unusual activity')) {
        const { setProviderCooldown } = require('../../utils/rate-limiter')
        const cooldownMs = 60 * 1000 // 1 min — longer than 429, this is a heavier flag
        setProviderCooldown('ChatGPT', cooldownMs)
        const err = new Error(`ChatGPT error 403: ${errText.slice(0, 300)}`)
        err.status = 403
        err.statusCode = 403
        err.cooldownMs = cooldownMs
        throw err
      }

      if (res.status !== 200) {
        console.error(`[ChatGPT] Got ${res.status}`)
      }

      const err = new Error(`ChatGPT error ${res.status}: ${errText.slice(0, 300)}`)
      err.status = res.status
      err.statusCode = res.status
      throw err
    }

    this._captureResponseHeaders(res)

    return this._nodeStream(res)
  }

  // ─── Conversation prepare (conduit token refresh) ───────────
  // HAR shows this is called before EVERY /f/conversation POST.
  // First call sends "x-conduit-token: no-token". Subsequent calls
  // send the previously returned conduit_token.

  async _prepareConversation(
    conversationId,
    parentMessageId,
    partialQuery,
    model = 'auto',
    attachmentMimeTypes = [],
  ) {
    const url = `${this.BASE_URL}/backend-api/f/conversation/prepare`
    const body = {
      action: 'next',
      fork_from_shared_post: false,
      parent_message_id: parentMessageId || 'client-created-root',
      model: model || 'auto',
      client_prepare_state: partialQuery ? 'success' : 'none',
      partial_query: partialQuery,
      timezone_offset_min: 420,
      timezone: 'America/Los_Angeles',
      conversation_mode: { kind: 'primary_assistant' },
      system_hints: [],
      ...(attachmentMimeTypes.length > 0 && { attachment_mime_types: attachmentMimeTypes }),
      supports_buffering: true,
      supported_encodings: ['v1'],
      client_contextual_info: { app_name: 'chatgpt.com' },
    }

    if (conversationId) {
      body.conversation_id = conversationId
    }

    const res = await this._fetch(url, {
      method: 'POST',
      headers: this._buildHeaders(
        {
          accept: '*/*',
          'x-conduit-token': this._headers['x-conduit-token'] || 'no-token',
        },
        '/backend-api/f/conversation/prepare',
      ),
      body: JSON.stringify(body),
    })

    if (!res.ok) {
      if (this._log) console.error(`[ChatGPT] Prepare conversation returned ${res.status}`)
      return
    }

    this._captureResponseHeaders(res)

    const data = await res.json()
    if (data.conduit_token) {
      this._headers['x-conduit-token'] = data.conduit_token
      if (this._log)
        console.debug('[ChatGPT] Conduit token from body for conversation:', conversationId)
    }
  }

  // ─── Sentinel refresh ─────────────────────────────────────────

  async _refreshSentinel() {
    if (!this._config) throw new Error('No proof token config for sentinel')

    const sentinelProof = ChatGPTProofOfWork.generateSentinelProof([...this._config])

    // Step 1: prepare — get prepare_token + POW/turnstile challenges
    const prepareUrl = `${this.BASE_URL}/backend-api/sentinel/chat-requirements/prepare`
    const prepareRes = await this._fetch(prepareUrl, {
      method: 'POST',
      headers: this._buildHeaders(
        { accept: '*/*', 'content-type': 'application/json' },
        '/backend-api/sentinel/chat-requirements/prepare',
      ),
      body: JSON.stringify({ p: sentinelProof }),
    })

    await assertOk(prepareRes, { prefix: 'Sentinel prepare ' })

    this._captureResponseHeaders(prepareRes)

    const prepareData = await prepareRes.json()
    if (!prepareData.prepare_token || !prepareData.proofofwork) {
      throw new Error(`Sentinel prepare unexpected: ${JSON.stringify(prepareData)}`)
    }

    const powProof = ChatGPTProofOfWork.solve(
      prepareData.proofofwork.seed,
      prepareData.proofofwork.difficulty,
      [...this._config],
    )

    // Step 2: finalize — submit prepare_token + solved POW (+ turnstile) to get the
    // chat-requirements token that goes on the actual /f/conversation request.
    const finalizeBody = {
      prepare_token: prepareData.prepare_token,
      proofofwork: powProof + '~S',
    }
    if (prepareData.turnstile?.dx) {
      finalizeBody.turnstile = prepareData.turnstile.dx
    }

    const finalizeUrl = `${this.BASE_URL}/backend-api/sentinel/chat-requirements/finalize`
    const finalizeRes = await this._fetch(finalizeUrl, {
      method: 'POST',
      headers: this._buildHeaders(
        { accept: '*/*', 'content-type': 'application/json' },
        '/backend-api/sentinel/chat-requirements/finalize',
      ),
      body: JSON.stringify(finalizeBody),
    })

    await assertOk(finalizeRes, { prefix: 'Sentinel finalize ' })

    this._captureResponseHeaders(finalizeRes)

    const finalizeData = await finalizeRes.json()
    if (!finalizeData.token) {
      throw new Error(`Sentinel finalize unexpected: ${JSON.stringify(finalizeData)}`)
    }

    this._headers['openai-sentinel-chat-requirements-token'] = finalizeData.token
    this._headers['openai-sentinel-proof-token'] = powProof + '~S'
    if (prepareData.turnstile?.dx) {
      this._headers['openai-sentinel-turnstile-token'] = prepareData.turnstile.dx
    }

    // Cookies captured automatically via _captureResponseHeaders → CookieJar
    // console.debug('[ChatGPT] Sentinel refreshed')
  }

  /**
   * Fetch current user info from /backend-api/me.
   * Used to verify session credentials are valid.
   * Returns user profile data on success, throws on failure.
   */
  async getCurrentUser() {
    const res = await this._fetch(
      `${this.BASE_URL}/backend-api/me`,
      {
        method: 'GET',
        headers: this._buildHeaders(),
      },
      true,
    )

    await assertOk(res, { prefix: 'Failed to get user info: ' })

    return res.data
  }

  // ─── Response header capture ─────────────────────────────────

  _captureResponseHeaders(res) {
    // Cookies + cookie header via BaseAPI
    super._captureResponseHeaders(res)

    const oaiIsUpdate = res.headers.get('x-oai-is-update')
    if (oaiIsUpdate) {
      this._headers['x-oai-is'] = oaiIsUpdate
      // console.debug('[ChatGPT] Updated x-oai-is from response header')
    }

    const conduitToken = res.headers.get('x-conduit-token')
    if (conduitToken) {
      this._headers['x-conduit-token'] = conduitToken
      // console.debug('[ChatGPT] Updated x-conduit-token from response header')
    }

    if (typeof this._onCaptureChanged === 'function') {
      try {
        this._onCaptureChanged({
          url: this._headers.__url || 'https://chatgpt.com/backend-api/f/conversation',
          method: 'POST',
          headers: { ...this._headers },
          body: this._bodyTemplate,
        })
      } catch (caughtErr) {
        console.error('this._onCaptureChanged() failed:', caughtErr)
      }
    }
  }

  // ─── Delete conversation ─────────────────────────────────────

  /**
   * Delete a single conversation server-side.
   * @param {string} conversationId - the conversation UUID to delete
   */
  async deleteSession(conversationId) {
    const url = `${this.BASE_URL}/backend-api/conversation/${conversationId}`
    const res = await this._fetch(url, {
      method: 'PATCH',
      headers: this._buildHeaders({ 'content-type': 'application/json' }),
      body: JSON.stringify({ is_visible: false }),
    })

    await assertOk(res, { allow: [404] })
  }

  // ─── Headers ──────────────────────────────────────────────────
  _buildHeaders(overrides = {}, targetPath = '') {
    const src = this._headers
    const isPrepare = targetPath?.includes('/conversation/prepare')
    const isConversation = targetPath?.includes('/conversation') && !isPrepare
    const cookieStr = this._cookies.toString()

    const base = {
      accept: overrides.accept || '*/*',
      'accept-encoding': 'gzip, deflate, br, zstd',
      'accept-language': src['accept-language'] || 'en-US,en;q=0.9',
      authorization: src['authorization'],
      'cache-control': 'no-cache',
      'content-type': overrides['content-type'] || 'application/json',
      ...(cookieStr && { cookie: cookieStr }),
      'oai-client-build-number': src['oai-client-build-number'] || '',
      'oai-client-version': src['oai-client-version'] || '',
      'oai-device-id': src['oai-device-id'] || '',
      ...(isConversation && { 'oai-echo-logs': src['oai-echo-logs'] || '' }),
      'oai-language': src['oai-language'] || 'en-US',
      'oai-session-id': src['oai-session-id'] || '',
      ...(isConversation && {
        'oai-telemetry': src['oai-telemetry'] || '',
        ...(src['openai-sentinel-chat-requirements-token'] && {
          'openai-sentinel-chat-requirements-token': src['openai-sentinel-chat-requirements-token'],
        }),
        ...(src['openai-sentinel-proof-token'] && {
          'openai-sentinel-proof-token': src['openai-sentinel-proof-token'],
        }),
        ...(src['openai-sentinel-turnstile-token'] && {
          'openai-sentinel-turnstile-token': src['openai-sentinel-turnstile-token'],
        }),
      }),
      origin: 'https://chatgpt.com',
      pragma: 'no-cache',
      priority: 'u=1, i',
      referer: src['referer'] || 'https://chatgpt.com/',
      'sec-ch-ua': src['sec-ch-ua'] || '',
      'sec-ch-ua-mobile': src['sec-ch-ua-mobile'] || '?0',
      'sec-ch-ua-platform': src['sec-ch-ua-platform'] || '',
      'sec-fetch-dest': 'empty',
      'sec-fetch-mode': 'cors',
      'sec-fetch-site': 'same-origin',
      'user-agent': src['user-agent'] || '',
      ...(isPrepare && { 'x-conduit-token': src['x-conduit-token'] || 'no-token' }),
      ...(src['x-oai-is'] && { 'x-oai-is': src['x-oai-is'] }),
      ...((isPrepare || isConversation) && {
        'x-oai-turn-trace-id': src['x-oai-turn-trace-id'] || '',
      }),
      ...(targetPath && {
        'x-openai-target-path': targetPath,
        'x-openai-target-route': targetPath,
      }),
    }

    const extra = { ...overrides }
    delete extra.accept
    delete extra['content-type']

    return { ...base, ...extra }
  }
}

module.exports = { ChatGPTAPI }
