'use strict'

/**
 * ChatGPT-specific recovery helpers.
 *
 * Wraps a ChatGPTAPI instance with:
 *
 *   - `withAuthRecovery(fn)`   — runs fn once; on HTTP 401, forces a full
 *     re-decode of the browser capture (fresh authorization + cookies) and
 *     retries exactly once. A second 401 is terminal.
 *   - `refreshSentinelSafe()`  — refreshes sentinel + conduit ahead of a turn
 *     and swallows failures that only affect a follow-up attempt (a stale
 *     token from the same process is still usable for the current request).
 *
 * The module never touches request bodies; it only inspects HTTP status and
 * header names.
 */

const ONE_SHOT_401 = 'chatgpt_401_retry_used'

function isUnauthorized(error) {
  if (!error) return false
  const status =
    Number.isInteger(error.status) && error.status > 0
      ? error.status
      : Number.isInteger(error.statusCode) && error.statusCode > 0
        ? error.statusCode
        : null
  return status === 401
}

/**
 * A 404 whose body says the upstream conversation was deleted. The auth is
 * still valid — only the conversation id is gone, so the caller must clear
 * the persisted id/parentId and let the next chatCompletion create a fresh
 * conversation. Detected by status + body marker, never by status alone: a
 * plain 404 could be an unrelated route change.
 */
function isConversationDeleted(error) {
  if (!error) return false
  const status =
    Number.isInteger(error.status) && error.status > 0
      ? error.status
      : Number.isInteger(error.statusCode) && error.statusCode > 0
        ? error.statusCode
        : null
  if (status !== 404) return false
  const text = String(error.message || '')
  return text.includes('conversation_deleted') || text.includes('Conversation has been deleted')
}

/**
 * Run fn() once. On a conversation_deleted 404, clear the session's upstream
 * conversation ids and retry exactly once so a fresh conversation is created.
 * Any other error propagates.
 */
async function withConversationRecovery(session, fn) {
  try {
    return await fn()
  } catch (error) {
    if (!isConversationDeleted(error)) throw error
    console.warn(
      'ChatGPT conversation was deleted upstream; clearing session ids and retrying once.',
    )
    session.id = null
    session.parentId = null
    return fn()
  }
}

/**
 * Force-re-apply the persisted browser capture from the SQLite user row.
 * State now lives in SQLite (temp/users.json was migrated away); the live
 * user row is the source of truth for headers/cookies.
 */
async function forceReloadCapture(api, userData) {
  if (!userData || typeof userData !== 'object' || !userData.parsedFetch) {
    return { ok: false, reason: 'no_user_row' }
  }
  try {
    await api.initializeFromJSON(userData.parsedFetch)
    return { ok: true, username: userData.username || 'unknown' }
  } catch (error) {
    console.error('api.initializeFromJSON() failed:', error)
    return { ok: false, reason: error && error.message ? error.message : String(error) }
  }
}

/**
 * Run fn() once. On 401, force-reload the capture and retry exactly once.
 * A second 401 propagates to the caller.
 */
async function withAuthRecovery(api, fn, userData = null) {
  try {
    return await fn()
  } catch (error) {
    console.error('chatgpt recovery: wrapped call failed:', error)
    if (!isUnauthorized(error)) throw error

    console.warn('ChatGPT returned 401; forcing a capture reload and retrying once.')
    const reload = await forceReloadCapture(api, userData)
    if (!reload.ok) {
      const wrapped = new Error(
        'ChatGPT returned 401 and the browser capture could not be reloaded (' +
          reload.reason +
          ').',
      )
      wrapped.status = 401
      wrapped.statusCode = 401
      wrapped.code = 'chatgpt_401_recovery_failed'
      throw wrapped
    }
    if (api[ONE_SHOT_401]) {
      // Already forced once this process; do not loop.
      const terminal = new Error('ChatGPT returned 401 again after a forced capture reload.')
      terminal.status = 401
      terminal.statusCode = 401
      terminal.code = 'chatgpt_401_after_recovery'
      throw terminal
    }
    api[ONE_SHOT_401] = true
    return fn()
  }
}

/**
 * Refresh sentinel + conduit before a turn. Any failure is logged, not
 * thrown: the request path may still succeed with the tokens the process
 * already holds, and a hard failure here would mask the real upstream error.
 */
async function refreshSentinelSafe(api) {
  try {
    if (typeof api._refreshSentinel === 'function') {
      await api._refreshSentinel()
      return { ok: true }
    }
    return { ok: false, reason: 'no_refresh_method' }
  } catch (error) {
    console.error('chatgpt recovery: sentinel refresh failed:', error)
    console.warn('Sentinel refresh failed: ' + (error.message || error))
    return { ok: false, reason: error && error.message ? error.message : String(error) }
  }
}

/**
 * Re-exported so the router can construct a wrapper without reaching into
 * the API internals more than once.
 */
function wrap(api) {
  return {
    api,
    withAuthRecovery: (fn, userData) => withAuthRecovery(api, fn, userData),
    refreshSentinelSafe: () => refreshSentinelSafe(api),
    forceReloadCapture: (userData) => forceReloadCapture(api, userData),
  }
}

module.exports = {
  ONE_SHOT_401,
  forceReloadCapture,
  isConversationDeleted,
  isUnauthorized,
  refreshSentinelSafe,
  withAuthRecovery,
  withConversationRecovery,
  wrap,
}
